async function history(tx,ctx,episodeId,escalationId,action,details={}){const a=actor(ctx),entry=Object.assign({id:id(),episodeId:episodeId||'',escalationId:escalationId||'',action,actor:a.user,actorName:a.name,actorRole:a.role,timestamp:now(),sourceKind:'SIMULADO'},details);await tx.unsafe(`insert into ${P}history(id,episode_id,escalation_id,payload) values($1,$2,$3,$4::jsonb)`,[entry.id,episodeId||null,escalationId||null,JSON.stringify(entry)]);await tx.unsafe(`insert into qx_simulation.qx_event_outbox(entity_type,entity_id,action,payload) values('PASP',$1,$2,$3::jsonb)`,[episodeId||escalationId||'',action,JSON.stringify({episodeId:episodeId||'',escalationId:escalationId||'',version:details.version||null,sourceKind:'SIMULADO'})]);return entry;}
async function lockEpisode(tx,episodeId){const rows=await tx.unsafe(`select id,version,payload from ${P}episodes where id=$1 for update`,[episodeId]);if(!rows.length)fail('Episodio PASP no encontrado.',404);if(object(rows[0].payload).sourceKind!=='SIMULADO')fail('Este módulo no puede modificar pacientes reales.',403);return rows[0];}
async function updateEpisode(tx,row,payload){const version=Number(row.version)+1;payload.version=version;payload.updatedAt=now();await tx.unsafe(`update ${P}episodes set version=$1,payload=$2::jsonb,updated_at=now() where id=$3`,[version,JSON.stringify(payload),row.id]);return payload;}
