function validateEpisode(b){if(b.sourceKind!=='SIMULADO'||b.simulationConfirmed!==true)fail('Confirme que los datos son SIMULADOS.');if(b.surgeryConfirmed!==true)fail('Confirme que la cirugía ya fue realizada.');const p={sourceKind:'SIMULADO',surgeryConfirmed:true,sourceCaseId:txt(b.sourceCaseId,140)};for(const key of ['patientName','documentNumber','phone','specialist','specialty','procedure'])p[key]=txt(b[key],key==='procedure'?500:180);if(!p.patientName||!p.documentNumber||!p.procedure)fail('Nombre, documento y procedimiento SIMULADOS son obligatorios.');p.surgeryDate=date(b.surgeryDate,'Fecha de cirugía',false);p.patientStatus=txt(b.patientStatus)||'Ambulatorio';if(!['Ambulatorio','Hospitalizado','Fallecido'].includes(p.patientStatus))fail('Estado de usuario inválido.');const a=object(b.appointment);p.appointment={date:date(a.date,'Cita POP'),time:time(a.time),sameSpecialist:txt(a.sameSpecialist)||'',status:txt(a.status)||(a.date?'Programada':'Pendiente')};if(!['Pendiente','Programada','Reprogramar cita','Asistió','No aplica','Fallecido'].includes(p.appointment.status))fail('Estado de cita inválido.');return p;}
function validateClinical(value,connected){const c=object(value),out={};if(!connected&&Object.values(c).some(x=>x!==''&&x!==null&&x!==undefined))fail('No hubo contacto: deje la evaluación clínica sin diligenciar.');if(!connected)return out;for(const key of CLINICAL_KEYS){if(c[key]===null||c[key]===undefined||c[key]==='')continue;const v=typeof c[key]==='boolean'?(c[key]?'Sí':'No'):txt(c[key],500);if(key==='painScore'&&!/^(?:[0-9]|10|No aplica|No contesta|Hospitalizado)$/.test(v))fail('EVA debe estar entre 0 y 10 o indicar que no pudo evaluarse.');out[key]=v;}return out;}
function urgent(c,classification){return norm(classification)==='HALLAZGO CLINICO URGENTE PRIORITARIO'||['dyspnea','chestPain','consciousnessChange','uncontrolledBleeding','severeUncontrolledPain','unableToUrinate','neurovascularChange','alteredConsciousness','urinaryRetention','progressiveLimbDeficit','catheterDrainageFailure','woundDeepOpening','clinicalDeterioration'].some(k=>norm(c[k])==='SI')||(norm(c.persistentVomiting)==='SI'&&norm(c.liquidTolerance)==='NO');}
function safeExtra(raw){const e=object(raw),out={};for(const k of ['identityVerified','authorizationConfirmed','respondent','contactMedium','communicationBarrier','educationProvided','teachBack','medicationAccess','deviceDetails','safetyInstruction','recordedInClinicalRecord']){const v=e[k];if(v!==undefined)out[k]=typeof v==='boolean'?v:txt(v,3000);}const details=object(e.details);out.details=Object.fromEntries(Object.entries(details).slice(0,30).filter(([k])=>/^[A-Za-z0-9_-]{1,60}$/.test(k)).map(([k,v])=>[k,txt(v,3000)]));return out;}
function validateCall(b,ctx,s){const c={},a=actor(ctx),stamp=bogota();c.id=id();c.episodeId=txt(b.episodeId,140);c.sourceKind='SIMULADO';c.number=b.number===undefined?null:Number(b.number);if(c.number!==null&&(!Number.isInteger(c.number)||c.number<1||c.number>1000))fail('Número de llamada inválido.');c.realDate=date(b.realDate||stamp.date,'Fecha real',false);c.time=time(b.time||stamp.time);c.recordedAt=now();c.professional=a.name;c.recordedBy=a.user;c.contactResult=txt(b.contactResult);if(!(s.lists?.['Resultado contacto']||CONTACT).includes(c.contactResult))fail('Resultado del contacto inválido.');const connected=c.contactResult==='Sí';c.clinical=validateClinical(b.clinical,connected);c.extra=safeExtra(b.extra);if(connected&&(c.extra.identityVerified!==true||c.extra.authorizationConfirmed!==true))fail('Confirme identidad y autorización del interlocutor para registrar una llamada efectiva.');c.observations=txt(b.observations,10000);const nonContactClass=c.contactResult==='Número errado'?'Hallazgo administrativo':c.contactResult==='No'?'No contesta':CONTACT.includes(c.contactResult)?c.contactResult:'Hallazgo administrativo';c.classification=txt(b.classification)||(!connected?nonContactClass:'');const list=s.lists?.['Clasificación hallazgo']||[];if(c.classification&&!list.includes(c.classification))fail('Clasificación del hallazgo inválida.');if(!connected&&c.classification==='Evolución esperada')fail('Sin contacto no puede concluir evolución esperada.');c.conduct=txt(b.conduct);if(c.conduct&&!(s.lists?.Conducta||[]).includes(c.conduct))fail('Conducta inválida.');for(const k of ['escalationResponsible'])c[k]=txt(b[k],180);for(const k of ['escalationDate','citationDate','scheduledDate'])c[k]=date(b[k],k);for(const k of ['appointmentAttendance','stitchesRemoved','woundReviewed']){const value=txt(b[k]);if(!connected&&value)fail('No hubo contacto: no registre asistencia ni procedimientos como observados.');if(value)c[k]=value;}c.urgentSafety=urgent(c.clinical,c.classification);if(connected&&(!c.classification||!c.conduct))fail('Para una llamada efectiva registre clasificación y conducta. La orientación urgente no debe esperar el formulario.');c.eventAssessment=c.classification==='Evento o incidente'?'SOSPECHA':'NO_DETERMINADO';return c;}
