  metric('appointment_min_days','Cita POP más pronta',appointmentDays.length?Math.min(...appointmentDays):0,null,'días','Menor intervalo calendario evaluable','No hay resultado cuando no existen citas evaluables.','INSTITUCIONAL',appointmentDays.length?Math.min(...appointmentDays):null);
  metric('appointment_max_days','Cita POP más demorada',appointmentDays.length?Math.max(...appointmentDays):0,null,'días','Mayor intervalo calendario evaluable','No hay resultado cuando no existen citas evaluables.','INSTITUCIONAL',appointmentDays.length?Math.max(...appointmentDays):null);
  metric('call_attempts','Fichas e intentos registrados',calls.length,null,'llamadas','Conteo de fichas individuales de todos los intentos','No cuenta las adendas como llamadas adicionales.','AMPLIACION');
  metric('effective_contacts','Llamadas con contacto efectivo',effectiveCalls.length,null,'llamadas','Intentos con resultado Sí','Identidad y autorización son verificadas al registrar la llamada.','AMPLIACION');
  metric('contact_rate','% de intentos con contacto efectivo',effectiveCalls.length,calls.length,'%','Intentos con Sí / Todos los intentos × 100','No sustituye cobertura ni oportunidad institucional.','AMPLIACION');
  metric('episodes_contacted','Episodios con contacto efectivo',contacted.size,null,'casos','Episodios distintos con al menos una llamada Sí','Dos llamadas efectivas al mismo episodio cuentan un caso.','AMPLIACION');
  metric('contact_episode_coverage','% episodios con contacto efectivo',contacted.size,episodes.length,'%','Episodios con al menos una llamada Sí / Total episodios × 100','Denominador por episodio, no por número de fichas.','AMPLIACION');
  const alarms=calls.filter(c=>c.urgentSafety===true),safety=escalations.filter(e=>norm(e.area)==='SEGURIDAD DEL PACIENTE'),safetyClosed=safety.filter(e=>e.status==='CERRADO'),open=escalations.filter(e=>!['RESUELTO','CERRADO'].includes(e.status));
  metric('urgent_alarms','Fichas con alerta urgente',alarms.length,null,'llamadas','Fichas con señal urgente registrada','No asigna categoría de triage ni confirma eventos adversos.','AMPLIACION');
  metric('escalations','Escalamientos registrados',escalations.length,null,'escalamientos','Conteo de escalamientos independientes','Crear un escalamiento no equivale a recepción, resolución ni notificación BN.','AMPLIACION');
  metric('coordination_escalations_open','Escalamientos pendientes de Coordinación',open.filter(e=>norm(e.area)!=='SEGURIDAD DEL PACIENTE').length,null,'escalamientos','Escalamientos no SP distintos de Resuelto/Cerrado','Requieren conducta, respuesta y verificación.','AMPLIACION');
  metric('safety_escalations','Escalamientos a Seguridad',safety.length,null,'escalamientos','Conteo de fichas de gestión Seguridad','No es el indicador de casos con BN=Sí.','AMPLIACION');
  metric('safety_escalations_closed','Investigaciones de Seguridad cerradas',safetyClosed.length,null,'escalamientos','Gestiones Seguridad con estado Cerrado','No cierra el seguimiento PASP ni confirma por sí solo evento adverso.','AMPLIACION');
  metric('safety_closure_rate','% cierre de gestiones Seguridad',safetyClosed.length,safety.length,'%','Gestiones Seguridad cerradas / Gestiones Seguridad × 100','Incluye investigación de sospechas descartadas o indeterminadas.','AMPLIACION');
  metric('appointment_late',`Citas POP >${maxPopDays} días`,appointmentDays.filter(d=>d>maxPopDays).length,null,'casos',`Citas evaluables con intervalo >${maxPopDays} días`,'Plazo institucional.','AMPLIACION');
  metric('appointment_early','Citas POP <7 días',appointmentDays.filter(d=>d<7).length,null,'casos','Citas evaluables con intervalo <7 días','Se identifica asignación anticipada sin penalizar.','AMPLIACION');
  metric('appointment_overdue_without_date',`Sin cita y plazo >${maxPopDays} días`,appointmentEligible.filter(e=>!validDate(e.appointment?.date)&&validDate(e.surgeryDate)&&(Date.parse(today+'T12:00:00Z')-Date.parse(e.surgeryDate+'T12:00:00Z'))/86400000>maxPopDays).length,null,'casos',`Episodios elegibles sin cita con más de ${maxPopDays} días desde cirugía`,'Evalúa a fecha actual de Bogotá; no aplica a procedimientos exentos.','AMPLIACION');
  const seriesMap=new Map();for(const e of episodes){const key=e.surgeryDate||'SIN_FECHA';if(!seriesMap.has(key))seriesMap.set(key,{date:key,episodes:0,attempts:0,effectiveContacts:0,firstCalls:0,secondCalls:0,urgentCalls:0,escalations:0});const row=seriesMap.get(key);row.episodes++;const ec=calls.filter(c=>c.episodeId===e.id);row.attempts+=ec.length;row.effectiveContacts+=ec.filter(effective).length;row.firstCalls+=ec.filter(c=>Number(c.number)===1&&recorded(c)).length;row.secondCalls+=ec.filter(c=>Number(c.number)===2&&recorded(c)).length;row.urgentCalls+=ec.filter(c=>c.urgentSafety===true).length;row.escalations+=escalations.filter(s=>s.episodeId===e.id).length;}
  const distributions={coordination:['Abierto','En seguimiento','Cerrado','No aplica'].map(label=>({label,count:coordination.filter(x=>x.state===label).length})),patientRoute:['Ambulatorio','Hospitalizado','Fallecido'].map(label=>({label,count:episodes.filter(e=>e.patientStatus===label).length})),contactResult:CONTACT.map(label=>({label,count:calls.filter(c=>c.contactResult===label).length})),classifications:[...new Set(firstTwo.map(c=>c.classification).filter(Boolean))].map(label=>({label,count:firstTwo.filter(c=>c.classification===label).length})),appointment:['Pendiente','Programada','Reprogramar cita','Asistió','No aplica','Fallecido'].map(label=>({label,count:episodes.filter(e=>e.appointment?.status===label).length}))};
  return {ok:true,sourceKind:'SIMULADO',checkedAt:now(),filters:{from,to,dateBasis:'SURGERY_DATE',inclusive:true},dateBasis:'SURGERY_DATE',totals:{episodes:episodes.length,attempts:calls.length,effectiveContacts:effectiveCalls.length,contactedEpisodes:contacted.size,firstCalls:firstRecorded.length,secondCalls:secondRecorded.length,urgentCalls:alarms.length,escalations:escalations.length},metrics,series:[...seriesMap.values()].sort((a,b)=>a.date.localeCompare(b.date)),distributions,notes:definitionFile.implementationNotes||['Indicadores de llamadas 1 y 2 preservan la fórmula institucional; los intentos y contactos adicionales se presentan por separado.','Activo sin revisión se representa como Abierto; Activo con revisión, En seguimiento.','Sin denominador, resultado no evaluable.','Datos simulados. Sin pacientes reales ni información clínica individual en esta respuesta.'],source:{url:INDICATOR_SOURCE,readOnlyDefinitions:true,realPatientDataImported:false}};
