async function indicators(ctx,url){
  requireAccess(callsPermission(ctx)||escalationReadPermission(ctx));
  const filters=Object.fromEntries(url.searchParams.entries());
  const settings=ctx.readApplicationSettings?await ctx.readApplicationSettings():{config:{}};
  return ctx.sql.begin(async tx=>{const data=await Promise.all([tx.unsafe(`select payload from ${P}episodes where source_kind='SIMULADO'`),tx.unsafe(`select c.payload from ${P}calls c join ${P}episodes e on e.id=c.episode_id where e.source_kind='SIMULADO'`),tx.unsafe(`select c.payload from ${P}escalations c join ${P}episodes e on e.id=c.episode_id where e.source_kind='SIMULADO'`)]);const result=calculatePaspIndicators(...data.map(rows=>rows.map(r=>object(r.payload))),filters,INDICATOR_DEFINITIONS,settings.config?.criteria);result.metrics=result.metrics.map(m=>({...m,...settings.config?.indicatorMetadata?.["PASP_"+m.id.toUpperCase()],criterionDays:settings.config?.criteria?.appointmentMaxDays||10}));return result;});
}
