    if(path==='/config'&&method==='GET'){requireAccess(callsPermission(ctx)||escalationReadPermission(ctx)||configPermission(ctx));if(url.searchParams.get('scope')==='SCHEMA'){requireAccess(configPermission(ctx));const rows=await ctx.sql.unsafe(`select version,payload from ${P}config where id='SCHEMA'`);return respond({ok:true,config:object(rows[0]?.payload),version:Number(rows[0]?.version||1),scope:'SCHEMA',sourceKind:'SIMULADO'});}const c=await config(ctx.sql);return respond({ok:true,...c,sourceKind:'SIMULADO'});}
    if(path==='/config'&&method==='POST'){requireAccess(configPermission(ctx));const b=await body(req);if(!txt(b.reason))fail('Documente el motivo de cambio.');const cfg=object(b.config),schemaEdit=b.scope==='SCHEMA'||url.searchParams.get('scope')==='SCHEMA',configId=schemaEdit?'SCHEMA':'SETTINGS';if(!schemaEdit&&cfg.maxContactAttempts!==null&&cfg.maxContactAttempts!==undefined&&(!Number.isInteger(Number(cfg.maxContactAttempts))||Number(cfg.maxContactAttempts)<1||Number(cfg.maxContactAttempts)>100))fail('Número de intentos inválido.');const result=await ctx.sql.begin(async tx=>{const rows=await tx.unsafe(`select id,version,payload from ${P}config where id=$1 for update`,[configId]);if(!rows.length)fail('Configuración PASP no inicializada.',503);checkVersion(b,rows[0]);const current=object(rows[0].payload),next=schemaEdit?validateSchema(cfg,current):validateSettings(Object.assign({},current,cfg,{sourceKind:'SIMULADO',maxContactAttempts:cfg.maxContactAttempts!==undefined?cfg.maxContactAttempts:cfg.minimumAttempts!==undefined?cfg.minimumAttempts:current.maxContactAttempts}),s),version=Number(rows[0].version)+1;await tx.unsafe(`update ${P}config set version=$1,payload=$2::jsonb,updated_at=now() where id=$3`,[version,JSON.stringify(next),configId]);await history(tx,ctx,null,null,schemaEdit?'ESQUEMA_PASP_EDITADO':'CONFIG_PASP_EDITADA',{version,reason:txt(b.reason,4000)});return {ok:true,config:next,version,scope:configId,sourceKind:'SIMULADO'};});return respond(result);}
    if(path==='/dictionary'&&method==='GET'){requireAccess(callsPermission(ctx)||configPermission(ctx));const rows=await ctx.sql.unsafe(`select id,version,payload from ${P}dictionary order by id`);return respond({ok:true,rows:rows.map(x=>normalizeDictionary(x.payload,x.id,Number(x.version)))});}
    if((path==='/dictionary'||path==='/care-guides')&&method==='POST')return respond(await catalogWrite(ctx,await body(req),path==='/dictionary'?'dictionary':'care_catalog'));
    if(path==='/episodes'&&method==='GET'){requireAccess(callsPermission(ctx)||escalationReadPermission(ctx));const limit=Math.min(250,Math.max(1,Number(url.searchParams.get('limit'))||100)),offset=Math.max(0,Number(url.searchParams.get('offset'))||0);const rows=await ctx.sql.unsafe(`select e.id,e.version,e.payload,(select count(*)::int from ${P}calls c where c.episode_id=e.id) as call_count from ${P}episodes e where e.source_kind='SIMULADO' order by e.created_at desc,e.id limit $1 offset $2`,[limit,offset]);const query=norm(url.searchParams.get('q')||''),list=rows.map(r=>Object.assign({},object(r.payload),{version:Number(r.version),callCount:Number(r.call_count||0)})).filter(e=>!query||norm([e.patientName,e.documentNumber,e.paspCode,e.procedure].join(' ')).includes(query)).map(e=>Object.assign(e,{matrix:matrix(e,s)}));return respond({ok:true,episodes:list,rows:list,limit,offset,sourceKind:'SIMULADO'});}
    if(path==='/episodes'&&method==='POST'){requireAccess(callsPermission(ctx));const b=await body(req),e=validateEpisode(b),cfg=(await config(ctx.sql)).config;if(e.sourceCaseId){const source=ctx.findCase?await ctx.findCase(e.sourceCaseId):null;if(!source||!['TRUE','SI','SÍ','1'].includes(String(source.payload?.OPERADO||'').toUpperCase()))fail('Solo se pueden registrar pacientes con cirugía realizada.');if(String(source.payload['DOCUMENTO']||'')!==e.documentNumber||String(source.payload['FECHA CIRUGÍA']||'')!==e.surgeryDate)fail('El paciente y la fecha deben corresponder a la cirugía realizada seleccionada.');const existing=await ctx.sql.unsafe(`select id from ${P}episodes where payload->>'sourceCaseId'=$1 limit 1`,[e.sourceCaseId]);if(existing.length)fail('Esta cirugía ya tiene un episodio. Registre una nueva llamada en su ficha existente.',409);}e.id=id();e.paspCode='SIM-PASP-'+e.id.slice(0,8).toUpperCase();e.registeredAt=bogota().date;e.createdAt=now();e.createdBy=actor(ctx).user;e.version=1;e.caseStatus='Abierto';e.coordinationStatus='Activo';e.coordination={status:'Activo',spNotified:'No'};e.safetyAlert='No';e.call1={scheduledDate:scheduled(e.surgeryDate,'first',cfg,s)};e.call2={scheduledDate:secondScheduled(e,cfg,s)};const result=await ctx.sql.begin(async tx=>{await tx.unsafe(`insert into ${P}episodes(id,payload) values($1,$2::jsonb)`,[e.id,JSON.stringify(e)]);await history(tx,ctx,e.id,null,'EPISODIO_SIMULADO_CREADO',{version:1,newState:e.caseStatus});return {ok:true,episode:Object.assign(e,{calls:[],escalations:[],history:[],matrix:matrix(e,s)})};});return respond(result,201);}
    const episodeMatch=path.match(/^\/episodes\/([^/]+)$/);if(episodeMatch&&method==='GET'){requireAccess(callsPermission(ctx)||escalationReadPermission(ctx));return respond({ok:true,episode:await fullEpisode(ctx.sql,episodeMatch[1],s)});}
